    _t1 = m_Q * g
    _t2 = m_Q * l
    _t3 = np.cross(np.cross(omega_q, q), x_L_dot) * _t2
    _t4 = np.cross(omega_q, np.cross(q, x_L_dot)) * (_t2 * -2)
    _t5 = np.cross(q, np.cross(omega_q, x_L_dot)) * _t2
